using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
public static class StreetLegendDrivingSceneBuilder{
 [MenuItem("Street Legend/Build Driving Chase Test Scene")]
 public static void Build(){var s=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientLight=new Color(.5f,.5f,.55f);Primitive(PrimitiveType.Cube,"Road",new Vector3(0,-.25f,35),new Vector3(18,.5f,100),new Color(.22f,.22f,.23f));Primitive(PrimitiveType.Cube,"Left verge",new Vector3(-10,-.1f,35),new Vector3(2,.2f,100),Color.green);Primitive(PrimitiveType.Cube,"Right verge",new Vector3(10,-.1f,35),new Vector3(2,.2f,100),Color.green);
 var player=Vehicle("Wanimo Car",new Vector3(0,1,0),new Color(.15f,.35f,.75f));player.tag="PlayerVehicle";var rb=player.AddComponent<Rigidbody>();player.AddComponent<StreetLegendVehicleController>();
 var target=Vehicle("Escaping Range Rover",new Vector3(2,1,20),new Color(.12f,.12f,.14f));target.AddComponent<StreetLegendChaseTarget>();
 Transform[] points=new Transform[3];for(int i=0;i<3;i++){var p=new GameObject("Target Route "+i);p.transform.position=new Vector3(i==1?5:-3,1,35+i*20);points[i]=p.transform;}target.GetComponent<StreetLegendChaseTarget>().route=points;
 Primitive(PrimitiveType.Cube,"Roadblock barrier",new Vector3(0,1,70),new Vector3(12,2,1),Color.yellow);var trigger=new GameObject("Roadblock Transition Trigger");trigger.transform.position=new Vector3(0,1,64);var col=trigger.AddComponent<BoxCollider>();col.isTrigger=true;col.size=new Vector3(18,3,8);trigger.AddComponent<StreetLegendRoadblockTrigger>();
 var phase=new GameObject("Mission Phase Coordinator").AddComponent<StreetLegendMissionPhase>();phase.vehicle=player.GetComponent<StreetLegendVehicleController>();
 var cam=new GameObject("Driving Camera").AddComponent<Camera>();cam.gameObject.AddComponent<StreetLegendDrivingCamera>().target=player.transform;
 new GameObject("Driving HUD").AddComponent<StreetLegendDrivingHUD>();
 var light=new GameObject("Sun").AddComponent<Light>();light.type=LightType.Directional;light.transform.rotation=Quaternion.Euler(45,-30,0);
 if(!AssetDatabase.IsValidFolder("Assets/Scenes"))AssetDatabase.CreateFolder("Assets","Scenes");EditorSceneManager.SaveScene(s,"Assets/Scenes/Level1_Driving_Test.unity");Debug.Log("Driving test scene generated. It is a separate test scene; not yet integrated with Hotel mission or runtime tested.");}
 static GameObject Vehicle(string name,Vector3 pos,Color c){var root=new GameObject(name);root.transform.position=pos;var body=Primitive(PrimitiveType.Cube,name+" Body",pos+new Vector3(0,.5f,0),new Vector3(2,1,4),c);body.transform.SetParent(root.transform,true);var rb=body.GetComponent<Rigidbody>();if(rb)Object.DestroyImmediate(rb);var col=body.GetComponent<BoxCollider>();if(col)Object.DestroyImmediate(col);root.AddComponent<BoxCollider>();return root;}
 static GameObject Primitive(PrimitiveType type,string name,Vector3 p,Vector3 scale,Color color){var g=GameObject.CreatePrimitive(type);g.name=name;g.transform.position=p;g.transform.localScale=scale;var m=new Material(Shader.Find("Standard"));m.color=color;g.GetComponent<Renderer>().sharedMaterial=m;return g;}
}
